private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || bb.remaining() == 0) {
        return i;
    }
    int utfChar = bb.get();
    if ((utfChar & 0x80) == 0) {
        sb.append((char) utfChar);
        i++;
    } else if ((utfChar & 0xE0) == 0xC0) {
        sb.append((char) ((utfChar & 0x1F) << 6 | (bb.get() & 0x3F)));
        i += 2;
    } else if ((utfChar & 0xF0) == 0xE0) {
        sb.append((char) ((utfChar & 0x0F) << 12 | (bb.get() & 0x3F) << 6 | (bb.get() & 0x3F)));
        i += 3;
    } else if ((utfChar & 0xF8) == 0xF0) {
        sb.append((char) ((utfChar & 0x07) << 18 | (bb.get() & 0x3F) << 12 | (bb.get() & 0x3F) << 6 | (bb.get() & 0x3F)));
        i += 4;
    }
    return i;
}
