private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int index = i;
    int len = bb.limit() - bb.position();
    while (index < i + len && index < bb.limit()) {
        int b = bb.get();
        if (b < 0) {
            index++;
            continue;
        }
        if ((b & 0xc0) == 0x80) {
            byte hi = (byte) (b & 0x3F);
            byte lo = bb.get();
            if (lo < 0) {
                index++;
                continue;
            }
            b = (hi << 6) | lo;
        }
        sb.append((char) b);
        index++;
    }
    // Move position to the next byte after the last decoded character
    bb.position(index);
    return i + len + (bb.remaining() != 0 ? 1 : 0);
}
