private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> leftSubtree = node.left;
    TreeNode<T> oldRoot = node;

    // Right rotation
    node.left = leftSubtree.right;
    leftSubtree.right = oldRoot;

    // Update node's parent and height
    oldRoot.right = null; // Optionally, set oldRoot.right to null if it was not meant to be a right child
    oldRoot.left = leftSubtree;
    oldRoot.height = Math.max(leftSubtree.height, oldRoot.right != null ? oldRoot.right.height : 0) + 1;

    return oldRoot;
}
```

