public void insertBefore(Bucket bucket) {
    // Find the index of the current bucket
    int currentIndex = 0;
    int index = -1;
    for (Bucket tmpBucket : buckets) {
        if (tmpBucket.equals(currentBucket)) {
            currentIndex = index;
            break;
        }
        index++;
    }
    if (currentIndex == -1 || index == 0) {
        throw new IllegalArgumentException("Current bucket is the first one or does not exist");
    }

    // Insert the new bucket before the current one
    buckets.add(index, bucket);
}
