public long readLong(int offset) {
    long currentValue = this.readInt(offset) & 0xFFFFFFFFL;
    int retryCount = 1;
    while ((this.readByte(offset + 4) == 1)) {
        currentValue = (currentValue << 8) | (this.readByte(offset + 5) & 0xFF);
        retryCount--;
        if (retryCount == 0) {
            throw new RuntimeException("Unsupported format for reading long value");
        }
    }
    while ((this.readByte(offset + 5) & 0xFF) >= 128) {
        currentValue = ((currentValue << 8) | (this.readByte(offset + 6) & 0xFF)) >>> 1;
        retryCount--;
        if (retryCount == 0) {
            throw new RuntimeException("Unsupported format for reading long value");
        }
    }
    if ((this.readByte(offset + 6) & 0xFF) < 128) {
        currentValue = (((currentValue << 8) | (this.readByte(offset + 7) & 0xFF)) << 6) | (this.readByte(offset + 8) & 0xFF);
    } else {
        currentUpperCase = 1;
        while (this.readByte(offset + 8) & 0xFF >= 128) {
            currentValue |= (this.readByte(offset + 9) & 0xFF) << 6;
            retryCount--;
            if (retryCount == 0) throw new RuntimeException("Unsupported format for reading long value");
        }
        currentUpperCase = 0;
        currentValue = (currentValue << 8) | (this.readByte(offset + 9) & 0xFF);
        while ((this.readByte(offset + 9) & 0xFF) >= 128) {
            currentValue = ((currentValue << 8) | (this.readByte(offset + 10) & 0xFF)) >>> 1;
            retryCount--;
            if (retryCount == 0) throw new RuntimeException("Unsupported format for reading long value");
        }
        currentValue |= (this.readByte(offset + 11) & 0xFF) << 6;
    }
    return currentValue;
}
