/**
 * Split time ranges to insure the start time and end time is small then  {@link #FETCH_DATA_DURATION}
 */
public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long maxDuration = FETCH_DATA_DURATION; // Assuming FETCH_DATA_DURATION has a predefined value
    while (start + maxDuration < end) {
        // Split the range into two parts
        TimeRange range1 = new TimeRange(start, start + maxDuration);
        TimeRange range2 = new TimeRange(start + maxDuration, end);
        timeRanges.add(range1);
        timeRanges.add(range2);
        start = start + maxDuration;
    }
    if (start < end) {
        // Add the last remaining part of the range
        TimeRange range = new TimeRange(start, end);
        timeRanges.add(range);
    }
    return timeRanges;
}
