public class TimeRangeBuilder {
    private long fetchDataDuration;
    private List<TimeRange> timeRanges;

    public TimeRangeBuilder(long fetchDataDuration) {
        this.fetchDataDuration = fetchDataDuration;
        this.timeRanges = new ArrayList<>();
    }

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        if (end - start > fetchDataDuration) {
            timeRanges.add(new TimeRange(start, start + fetchDataDuration));
            if (end > fetchDataDuration) {
                timeRanges.add(new TimeRange(end - fetchDataDuration, end));
            }
        } else {
            timeRanges.add(new TimeRange(start, end));
        }
        return timeRanges;
    }

    // Getters and setters for fetchDataDuration and timeRanges
    public void setFetchDataDuration(long fetchDataDuration) {
        this.fetchDataDuration = fetchDataDuration;
    }

    public long getFetchDataDuration() {
        return fetchDataDuration;
    }

    public List<TimeRange> getTimeRanges() {
        return timeRanges;
    }

    public void setTimeRanges(List<TimeRange> timeRanges) {
        this.timeRanges = timeRanges;
    }
