public List<TimeRange> buildTimeRanges(long start, long end) throws Exception {
    long duration = end - start;
    long fetchDataDuration = 24 * 60 * 60; // 1 day in milliseconds
    List<TimeRange> ranges = new ArrayList<>();

    if (duration < fetchDataDuration) {
        ranges.add(new TimeRange(start, end));
    } else {
        long initialDuration = duration - fetchDataDuration;
        long numRanges = initialDuration / fetchDataDuration;
        long remainingDuration = initialDuration % fetchDataDuration;

        for (int i = 0; i < numRanges; i++) {
            ranges.add(new TimeRange(start, start + fetchDataDuration));
            start += fetchDataDuration;
        }

        if (remainingDuration > 0) {
            ranges.add(new TimeRange(start, start + remainingDuration));
            start += remainingDuration;
        }
    }

    return ranges;
}
