    List<TimeRange> result = new ArrayList<>();
    long duration = Math.min(FETCH_DATA_DURATION, end - start);
    long step = templateHelper.getBatchDataDuration();
    for (long i = start; i <= end - step; i += step) {
        TimeRange timeRange = new TimeRange();
        timeRange.setStartTime(i);
        timeRange.setEndTime(i + step);
        result.add(timeRange);
    }
    if (end - start %% step != 0) {
        TimeRange lastTimeRange = new TimeRange();
        lastTimeRange.setStartTime(end - step);
        lastTimeRange.setEndTime(end);
        result.add(lastTimeRange);
    }
    return result;
}
