static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate how many days have passed since the first day
    int daysSinceFirstDay = (int) (timeBucket / 10000000);

    // Determine the modulus to get the day within the month
    int dayMod = daysSinceFirstDay % dayStep;

    // Convert the day back to a time bucket value
    long compressedTimeBucket = dayMod * 10000000;

    return compressedTimeBucket;
}
