static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day from the time bucket
    int year = (int) ((timeBucket / (12 * 30)) % 100); // Year divided by 12 times 30 to get the year part
    int month = (int) ((timeBucket % (12 * 30)) / 30);  // Month divided by 12 times 30 to get the month part
    int day = (int) (timeBucket % 30);                  // Day part

    // Adjust the day based on dayStep
    day -= (day - 1) % dayStep;

    // Put the year, month, and day back together to form the new time bucket
    return year * (12 * 30) + month * 30 + day;
}
