public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int len0 = 0, end = index; // end position in string
    while (end < index + len) {
        if (((str.charAt(end) >>> 7) & 0x7f) == 0x00) { // 1 byte char. 0bbbbbbb
            end++;
            len0++;
        } else if (((str.charAt(end) >>> 5) & 0x1f) == 0x06) { // 2 byte char. 110xxxxx 10xxxxxx
            end += 2;
            len0 += 2;
        } else if (((str.charAt(end) >>> 4) & 0x0f) == 0x0E) { // 3 byte char. 1110xxxx 10xxxxxx 10xxxxxx
            end += 3;
            len0 += 3;
        } else if (((str.charAt(end) >>> 3) & 0x07) == 0x1C) { // 4 byte char. 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx
            end += 4;
            len0 += 4;
        }
    }
    return len0;
