private static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (index < 0 || index > str.length()){
        return 0;
    }

    final byte[] array = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
    int i = index;
    int utf8Size = 0;

    while (i < index + len){
        byte b1 = array[i];
        if (b1 >= 0 && b1 <= 127){
            utf8Size++;
            i++;
        } else if (b1 >= 128 && b1 <= 223){
            utf8Size += 2;
            i += 2;
        } else if (b1 >= 224 && b1 <= 239){
            utf8Size += 3;
            i += 3;
        } else if (b1 >= 240 && b1 <= 247){
            utf8Size += 4;
            i += 4;
        } else {
            utf8Size += 5;
            i += 5;
        }
    }

    return utf8Size;
}
