public static int computeUTF8Size(CharSequence str, int index, int len) {
    if (str == null) {
        throw new NullPointerException("The CharSequence cannot be null");
    }
    final int length = str.length();
    if (index < 0 || index >= length) {
        throw new IllegalArgumentException("The index is out of bounds");
    }
    final int end = Math.min(index + len, length);
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 127) {
            size++;
        } else if (ch <= 2047) {
            size += 2;
        } else if (ch <= 65535) {
            size += 3;
        }
    }
    return size;
}
