        while (i < index + len) {
            int b = (char) str.charAt(i);
            if (b < 0x80) {
                utf8Size += 1;
            } else if (b < 0xC0) {
                utf8Size += 2;
            } else if (b < 0xE0) {
                utf8Size += 3;
            } else if (b < 0xF0) {
                utf8Size += 4;
