public static void writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    int length = str.length();
    byte[] utf8Bytes = new byte[length * 3];
    for (int i = 0; i < length; i++) {
        int c = str.charAt(i);
        if ((c >= 0 && c <= 127) || (c >= 192 && c <= 223)) {
            utf8Bytes[i] = (byte) c;
        } else if (c >= 224 && c <= 239) {
            utf8Bytes[i] = (byte) (192 | (c >> 6) & 0x1F);
            utf8Bytes[i + 1] = (byte) (128 | (c & 0x3F));
        } else if (c >= 240 && c <= 247) {
            utf8Bytes[i] = (byte) (224 | (c >> 6) & 0x1F);
            utf8Bytes[i + 1] = (byte) (128 | (c >> 4) & 0x3F);
            utf8Bytes[i + 2] = (byte) (128 | (c & 0x3F));
        } else if (c >= 248 && c <= 251) {
            utf8Bytes[i] = (byte) (240 | (c >> 6) & 0x1F);
            utf8Bytes[i + 1] = (byte) (128 | (c >> 2) & 0x3F);
            utf8Bytes[i + 2] = (byte) (128 | (c & 0x3F));
            utf8Bytes[i + 3] = (byte) (128 | (c >> 0) & 0x3F);
        } else if (c >= 252 && c <= 255) {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    session.write(utf8Bytes);
}
