private static List<PathSegmentImpl> decodePath(String path, boolean decode, Protocol protocol) {
    // Decode URI encoding if specified
    if (decode) {
        path = URLDecoder.decode(path, getDefaultEncoding());
    }

    // Split path into segments based on delimiter
    String[] pathSegments = path.split(getPathDelimiter(protocol));

    // Convert each segment into PathSegmentImpl
    List<PathSegmentImpl> segments = new ArrayList<>();
    for (String segment : pathSegments) {
        segments.add(new PathSegmentImpl(segment));
    }

    return segments;
}

private static String getDefaultEncoding() {
    return "UTF-8";
}

private static String getPathDelimiter(Protocol protocol) {
    switch (protocol) {
        case HTTP:
        case HTTPS:
        case REGISTRATION_DNS:
            return "/";
        default:
            throw new IllegalArgumentException("Unsupported protocol");
    }
}

static enum Protocol {
    HTTP,
    HTTPS,
    REGISTRATION_DNS
