import java.util.List;

public class PathSegmentDecoder {

    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        if (u == null) {
            return Collections.emptyList();
        }

        String path = u.getPath();
        if (path == null || path.isEmpty()) {
            return Collections.emptyList();
        }

        String decodePath = path;
        if (decode) {
            decodePath = decodePath.replaceAll("%2F", "/").replaceAll("%20", " ");
        }

        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String[] parts = decodePath.split("/");
        for (String part : parts) {
            if (part != null && !part.isEmpty()) {
                pathSegments.add(new PathSegmentImpl(part));
            }
        }

        return pathSegments;
    }
