    private Point2D location;

    public Size2D splitAlongXAxis(Box2D box) {
        double width = box.getSize().getWidth();
        double halfWidth = width / 2;
        Point2D halfLocation = box.getLocation().getTranslated(0, halfWidth);

        Size2D leftBoxSize = new Dimension2D(halfWidth, box.getSize().getHeight());
        Size2D rightBoxSize = new Dimension2D(width - halfWidth, box.getSize().getHeight());

        Box2D leftBox = new Box2D(halfLocation, leftBoxSize);
        Box2D rightBox = new Box2D(halfLocation, rightBoxSize);

        return new Pair<>(leftBox, rightBox);
    }
}
