import java.awt.geom.Rectangle2D;
import java.awt.geom.Point2D.Double;

public class BoxUtils {

    /**
     * Split a box along the x axis into two equal boxes.
     * @param box the box to split
     * @return a pair with the two resulting boxes
     */
    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
        // Define the midpoint of the box along the x-axis
        double midX = (box.getMinX() + box.getMaxX()) / 2;

        // Calculate the new x-coordinate for the midpoint of each resulting box
        double newMidX = midX - (box.getMaxX() - box.getMinX()) / 2;

        // Create the two resulting boxes
        Box2D leftBox = new Rectangle2D.Double(box.getMinX(), box.getMinY(), newMidX - box.getMinX(), box.getHeight());
        Box2D rightBox = new Rectangle2D.Double(newMidX, box.getMinY(), box.getMaxX() - newMidX, box.getHeight());

        return new Pair<>(leftBox, rightBox);
    }
}
