public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    Node<Data> current = node;
    while (current != null) {
        // Write dataNode data
        ObjectOutputStream oos = new ObjectOutputStream(out);
        oos.writeObject(current.getData());
        oos.close();

        // Increase total size by the size of the dataNode data
        totalSize += current.getData().length;

        // Move to the next dataNode
        current = current.getNext();
    }
    return totalSize;
}
