    int len = str.length();
    int i = 0;

    while (i < len) {
        if (i + 3 < len && str.substring(i, i + 3).equals("''") && str.charAt(i) != '\\') {
            unescaped.append("''");
            i += 3;
        } else if (i + 3 < len && str.substring(i, i + 3).equals("''") && str.charAt(i) == '\\') {
            unescaped.append("'");
            i += 3;
        } else if (i + 1 < len && str.charAt(i) == '\\') {
            switch (str.charAt(i + 1)) {
                case 'n':
                    unescaped.append('\n');
                    i += 2;
                    break;
                case 't':
                    unescaped.append('\t');
                    i += 2;
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\");
            }
        } else {
