import org.jsoup.nodes.Node;

public class OuterFaceCirculator {
    private Node start;
    private Node stop;
    private int dir;
    private Predicate<Node> predicate;

    public OuterFaceCirculator(Predicate<Node> predicate, Node start, Node stop, int dir) {
        this.predicate = predicate;
        this.start = start;
        this.stop = stop;
        this.dir = dir;
    }

    public Node selectOnOuterFace() {
        Node current = start.clone();

        while (true) {
            if (predicate.test(current)) {
                return current;
            }

            if (current == stop) {
                return stop;
            }

            current = current.sibling(node -> dir == Node.ELEMENT_TAG ? node.nextSibling() : node.previousSibling());
        }
    }
}
