    // Empty the result and reset the match pattern
    reset();
    // Match the current URI against the pattern
    int start = findSubpatternBoundary(0);
    int end = findSubpatternBoundary(uri.length());
    String subpattern = uri.substring(start, end);
    // Count the leading and trailing slashes in the subpattern
    int count = subpattern.length() - subpattern.replaceAll("\\\\/+(?=\\\\)", "").length();
    // Calculate the position to restart from
    int breakIndex = findBreakIndex(uri, start, count);
    if (breakIndex != -1) {
        setStartPosition(breakIndex);
        return new MatchResult(subpattern, start, end);
    }    
    // Count the number of consecutive slashes at the end of the subpattern
    int slashCount = subpattern.length() - subpattern.replaceAll("(?<=\\\\)\\\\/+(?=\\\\)", "").length();
    // Check if the number of trailing slashes matches the number of consecutive slashes at the end of the pattern
    if (slashCount == 0) {
        setStartPosition(uri.length() - subpattern.length());
        return new MatchResult(subpattern, start, end);
    }
    if (slashCount == 0) {
        setStartPosition(uri.length() - subpattern.length());
        return new MatchResult(subpattern, start, end);
    }
    return null;
