protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // create a new graph path
    GraphPath<V,E> path = new GraphPath<>();

    // add each edge in the tour to the graph path
    for (E edge : tour) {
        Destiny<V,E> dest = graph.getEdgeDestination(edge);
        Source<V,E> src = graph.getEdgeSource(edge);
        path.add(dest);
        if (src != dest) {
            path.add(src);
        }
    }

    // set the start and end nodes of the path
    path.setStart(tour.iterator().next().getSource());
    path.setEnd(tour.lastIndexOf(tour.iterator().next()).getDestination());

    // return the completed graph path
    return path; 
}
