public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Create a new GraphPath object with the specified graph
    GraphPath<V,E> graphPath = new GraphPath<>(graph);

    // Start from the first edge in the tour (assuming it is the first element)
    E firstEdge = null;
    int i = 0;
    for (E edge : tour) {
        if (i == 0) {
            firstEdge = edge;
        }
        i++;
    }

    // Add the edges of the tour to the graph path
    for (E edge : tour) {
        graphPath.addEdge(graph.getEdge(edge));
    }

    // Set the source vertex of the graph path to the first edge's source
    graphPath.setSource(firstEdge.getSource());

    // Return the resulting graph path
    return graphPath;
}
