        if (loc1 == -1) {
            return Class.forName(className);
        } else {
            String simpleClassName = loc0.substring(loc1 + 1);
            String packageName = loc0.substring(0, loc1);

            try {
                return Class.forName(packageName + ".Class.forName(simpleClassName)");
            } catch (ClassNotFoundException e) {
                throw new ClassNotFoundException("Class can not be found: " + className);
            }
        }
