public static String base64Decode(final String s){
    int len = s.length();
    byte[] decodedBytes = new byte[len / 4];
    for (int i = 0, j = 0; i < len; i += 4) {
        decodedBytes[j++] = (byte) ((base64ToByte(s.charAt(i)) << 18) | 
                                (base64ToByte(s.charAt(i + 1)) << 12) | 
                                (base64ToByte(s.charAt(i + 2)) << 6) | 
                                base64ToByte(s.charAt(i + 3)));
    } 
    return new String(decodedBytes);
}
