public static String base64Decode(final String s) {
    ByteArrayOutputStream bos = new ByteArrayOutputStream();
    int i = 0;
    while (i < s.length()) {
        char c = s.charAt(i++);
        if (c >= 'A' && c <= 'Z') {
            bos.write(c - 'A');
        } else if (c >= 'a' && c <= 'z') {
            bos.write(c - 'a');
        } else if (c >= '0' && c <= '9') {
            bos.write(c - '0');
        } else if (c == '+') {
            bos.write(62);
        } else if (c == '/') {
            bos.write(63);
        }
    }
    return new String(bos.toByteArray());
}
