private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<List<Pair<Integer,Integer>>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.edgeSet()) {
        List<List<Pair<Integer,Integer>>> neighborhoodSeparators = new ArrayList<>();
        List<Integer> neighbors = graph.adjList(edge);
        for (int neighbor : neighbors) {
            List<Pair<Integer,Integer>> separator = new ArrayList<>();
            for (E neighborEdge : graph.edgeSet()) {
                if (neighborEdge == edge) continue;
                if (graph.adjList(neighborEdge).contains(neighbor)) separator.add(Pair.with(neighborEdge, neighbor));
