private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (graph == null || vertices == null || vertices.size() == 0) {
        return false;
    }
    UndirectedGraph<V,E> inducedGraph = getInducedGraph(graph, vertices);
    if (inducedGraph == null || inducedGraph.numberOfVertices() == 0) {
        return false;
    }
    return inducedGraph.numberOfEdges() == inducedGraph.numberOfVertices() - 1;
}

private static <V,E>UndirectedGraph<V,E> getInducedGraph(Graph<V,E> graph,Set<V> vertices){
    UndirectedGraph<V,E> inducedGraph = new UndirectedGraph<>(graph.getEdgeClass());
    for (V vertex : graph.vertices()) {
        if (vertices.contains(vertex)) {
            inducedGraph.addVertex(vertex);
        }
    }
    for (Edge<V,E> edge : graph.edges()) {
        V source = edge.getSource();
        V target = edge.getTarget();
        if (vertices.contains(source) && vertices.contains(target)) {
            inducedGraph.addEdge(source, target, edge.getEdgeLabel());
        }
    }
    return inducedGraph;
}
