    if (Character.isAscii(ch)) {
        // Cache the String objects for ASCII characters to avoid repeatedly creating new ones
        if (coaches == null) {
            coaches = new HashMap<>(256);
        }
        String cachedString = coaches.get(ch);
        if (cachedString == null) {
            cachedString = Character.toString(ch);
            coaches.put(ch, cachedString);
        }
        return cachedString;
    } else {
        // For non-ASCII characters, use the standard String constructor
        return Character.toString(ch);
    }
}
