import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

public class ThreadSnapshotsParser {

    public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            // Skip header line
            reader.readLine();

            while ((line = reader.readLine()) != null) {
                String[] parts = line.split(",");
                if (parts.length >= 15) { // Assuming there are 15 columns
                    LocalDateTime startDateTime = LocalDateTime.parse(parts[1], DATE_TIME_FORMAT);
                    LocalDateTime endDateTime = LocalDateTime.parse(parts[2], DATE_TIME_FORMAT);
                    long startTime = startDateTime.toEpochSecond(ZoneOffset.UTC);
                    long endTime = endDateTime.toEpochSecond(ZoneOffset.UTC);

                    // Check if current line falls within any of the time ranges
                    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                        if (timeRange.contains(startTime, endTime)) {
                            long callId = Long.parseLong(parts[3]);
                            String className = parts[4];
                            String methodName = parts[5];
                            long duration = Long.parseLong(parts[6]);
                            String threadName = parts[7];
                            String lockedObjectClass = parts[8];
                            long lockedObjectId = Long.parseLong(parts[9]);
                            String heapObjectId = parts[10];
                            int startCpuTime = Integer.parseInt(parts[11]);
                            int endCpuTime = Integer.parseInt(parts[12]);
                            int systemCpuTime = Integer.parseInt(parts[13]);
                            int utilizedSystemCpuTime = Integer.parseInt(parts[14]);
